def classify_layout(catalog: str, schema_names: list[str]) -> str:
    """'a' when the catalog is named for an environment, 'b' when it is <env>_<domain>, 'c' when its schemas are."""
    if catalog.lower() in ENVIRONMENTS:
        return "a"
    if environment_of(catalog):
        return "b"
    if any(environment_of(s) for s in schema_names if s != "information_schema"):
        return "c"
    return "unknown"

def three_level_name(layout: str, env: str, table: str = "daily_revenue", domain: str = "sales") -> str:
    """The catalog.schema.table a sales table gets in each layout."""
    if layout == "a":
        return f"{env}.{domain}.{table}"
    if layout == "b":
        return f"{env}_{domain}.reporting.{table}"
    if layout == "c":
        return f"analytics.{env}_{domain}.{table}"
    raise ValueError(f"unknown layout {layout!r}")

-- One external location per environment, on that environment's own bucket or container.
CREATE EXTERNAL LOCATION IF NOT EXISTS dev_managed   URL 's3://<dev-bucket>/unity'   WITH (STORAGE CREDENTIAL dev_storage);
CREATE EXTERNAL LOCATION IF NOT EXISTS test_managed  URL 's3://<test-bucket>/unity'  WITH (STORAGE CREDENTIAL test_storage);
CREATE EXTERNAL LOCATION IF NOT EXISTS stage_managed URL 's3://<stage-bucket>/unity' WITH (STORAGE CREDENTIAL stage_storage);
CREATE EXTERNAL LOCATION IF NOT EXISTS prod_managed  URL 's3://<prod-bucket>/unity'  WITH (STORAGE CREDENTIAL prod_storage);

-- The catalog creator needs CREATE CATALOG on the metastore and CREATE MANAGED STORAGE on the location.
GRANT CREATE MANAGED STORAGE ON EXTERNAL LOCATION prod_managed TO `platform-admins`;

-- One catalog per environment. MANAGED LOCATION must sit inside the matching external location.
CREATE CATALOG IF NOT EXISTS dev   MANAGED LOCATION 's3://<dev-bucket>/unity/dev'     COMMENT 'dev environment';
CREATE CATALOG IF NOT EXISTS test  MANAGED LOCATION 's3://<test-bucket>/unity/test'   COMMENT 'test environment';
CREATE CATALOG IF NOT EXISTS stage MANAGED LOCATION 's3://<stage-bucket>/unity/stage' COMMENT 'stage environment';
CREATE CATALOG IF NOT EXISTS prod  MANAGED LOCATION 's3://<prod-bucket>/unity/prod'   COMMENT 'prod environment';

-- Domain schemas inside each catalog. The bundle's schema variable points at one of these.
CREATE SCHEMA IF NOT EXISTS dev.sales;
CREATE SCHEMA IF NOT EXISTS test.sales;
CREATE SCHEMA IF NOT EXISTS stage.sales;
CREATE SCHEMA IF NOT EXISTS prod.sales;

-- dev: engineers build freely, including a schema of their own for a sandbox.
GRANT ALL PRIVILEGES ON CATALOG dev TO `dev-engineers`;

-- test and stage: engineers read and the environment's service principal writes.
ALTER CATALOG test  OWNER TO `<test-run-as-service-principal-application-id>`;
ALTER CATALOG stage OWNER TO `<stage-run-as-service-principal-application-id>`;
GRANT USE CATALOG, USE SCHEMA, SELECT ON CATALOG test  TO `dev-engineers`;
GRANT USE CATALOG, USE SCHEMA, SELECT ON CATALOG stage TO `dev-engineers`;

-- prod: people read, only the service principal writes. The owner has every privilege, so make
-- the run-as service principal the owner and nobody else needs write grants.
ALTER CATALOG prod OWNER TO `<prod-run-as-service-principal-application-id>`;
GRANT USE CATALOG, USE SCHEMA, SELECT ON CATALOG prod TO `prod-analysts`;
GRANT USE CATALOG, USE SCHEMA, SELECT ON CATALOG prod TO `dev-engineers`;

-- The deploy service principal creates schemas and the jobs that fill them. It does not need the data.
GRANT USE CATALOG, CREATE SCHEMA ON CATALOG prod TO `<prod-deploy-service-principal-application-id>`;

