def write_xlsx(path: str, headers: list[str], rows: list[list], decimal_columns: set[str]) -> None:
    from openpyxl import Workbook
    from openpyxl.styles import Alignment, Font, PatternFill

    workbook = Workbook()
    sheet = workbook.active
    sheet.title = "accounts"
    sheet.append(headers)
    for row in rows:
        sheet.append(row)
    header_fill = PatternFill("solid", fgColor="1B3139")
    for cell in sheet[1]:
        cell.font = Font(bold=True, color="FFFFFF")
        cell.fill = header_fill
        cell.alignment = Alignment(horizontal="center")
    for index, width in enumerate(column_widths(headers, rows), start=1):
        sheet.column_dimensions[sheet.cell(row=1, column=index).column_letter].width = width
    for index, name in enumerate(headers, start=1):
        if name in decimal_columns:
            for cell in sheet.iter_cols(min_col=index, max_col=index, min_row=2):
                for item in cell:
                    item.number_format = "#,##0.00"
    sheet.freeze_panes = "A2"
    workbook.save(path)

def column_widths(headers: Sequence[str], rows: Iterable[Sequence[Any]]) -> list[int]:
    """Character width per column: the longest value or header, padded and clamped."""
    widths = [len(str(header)) for header in headers]
    for row in rows:
        for index, value in enumerate(row):
            widths[index] = max(widths[index], len("" if value is None else str(value)))
    return [min(MAX_WIDTH, max(MIN_WIDTH, width + PADDING)) for width in widths]

